$policy = @'
{
  "Rules": [
    {
      "ID": "MoveToIAAfter30Days",
      "Status": "Enabled",
      "Prefix": "uploads/",
      "Transitions": [
        { "Days": 30, "StorageClass": "STANDARD_IA" }
      ],
      "Expiration": { "Days": 365 }
    }
  ]
}
'@

Set-Content -Path lifecycle.json -Value $policy
aws s3api put-bucket-lifecycle-configuration --bucket aspnet-aws-demo-bucket --lifecycle-configuration file://lifecycle.json

$corsConfig = @'
{
  "CORSRules": [
    {
      "AllowedOrigins": ["https://myapp.com", "http://localhost:5000"],
      "AllowedMethods": ["GET", "PUT", "POST"],
      "AllowedHeaders": ["*"],
      "ExposeHeaders": ["ETag"],
      "MaxAgeSeconds": 3000
    }
  ]
}
'@

Set-Content -Path cors.json -Value $corsConfig
aws s3api put-bucket-cors --bucket aspnet-aws-demo-bucket --cors-configuration file://cors.json
